const fs = require('node:fs');

fs.writeFileSync('src/main.tsx', "'`// Preconfigured Gravity UI setup is ALREADY wired here (both CSS imports + ThemeProvider).
import '"'@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React, { useCallback, useState } from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider, type Theme } from '@gravity-ui/uikit';

import { App } from './App';

const THEME_STORAGE_KEY = 'theme';

function getInitialTheme(): Theme {
  return window.localStorage.getItem(THEME_STORAGE_KEY) === 'dark' ? 'dark' : 'light';
}

function ThemeState() {
  const [theme, setTheme] = useState<Theme>(getInitialTheme);
  const handleThemeChange = useCallback((newTheme: Theme) => {
    setTheme(newTheme);
    window.localStorage.setItem(THEME_STORAGE_KEY, newTheme);
  }, []);

  return (
    <ThemeProvider theme={theme}>
      <App theme={theme} onThemeChange={handleThemeChange} />
    </ThemeProvider>
  );
}

ReactDOM.createRoot(document.getElementById('root')"'!).render(
  <React.StrictMode>
    <ThemeState />
  </React.StrictMode>,
);
`);

fs.writeFileSync('"'src/App.tsx', "'`import { Switch, type Theme } from '"'@gravity-ui/uikit';

type AppProps = {
  theme: Theme;
  onThemeChange: (theme: Theme) => void;
};

export function App({ theme, onThemeChange }: AppProps) {
  const darkThemeSelected = theme === 'dark';

  return (
    <div style={{ padding: 24 }}>
      <Switch
        checked={darkThemeSelected}
        onChange={(event) => onThemeChange(event.target.checked ? 'dark' : 'light')}
        label=\"Dark theme\"
      />
    </div>
  );
}
"'`);
NODE
npm run build'

